const r = $('Get DR Report (deterministic)').first().json;
const summary = $input.first().json.text || '';
const fmt = n => new Intl.NumberFormat('vi-VN').format(n);
const regionLines = (r.ngan_sach_khu_vuc || []).map(x => `• ${x.region}: chi phí ${fmt(x.cost_vnd)} đ, LN ${x.profit_pct}%`).join('\n');
const orderLines = (r.loi_nhuan_theo_don || []).map(x => `• ${x.order_code}: LN ${x.profit_pct}% (${fmt(x.revenue_vnd - x.cost_vnd)} đ)`).join('\n');
// Stub xuất Google Docs — thay $env.DOCS_URL bằng Body /api/google/docs-create ở prod
const docs_body = JSON.stringify({ template: 'DR_report', period: r.period, data: r, summary });
const notify_body = JSON.stringify({ channel: 'discord', title: '📊 Báo cáo ĐR kỳ (' + r.period + ')', color: 3447003, description: summary, fields: [ { name: 'Chi phí B', value: fmt(r.chi_phi_B) + ' đ', inline: true }, { name: 'Doanh thu', value: fmt(r.doanh_thu) + ' đ', inline: true }, { name: 'Lợi nhuận', value: fmt(r.loi_nhuan) + ' đ (' + r.loi_nhuan_pct + '%)', inline: true }, { name: 'Ngân sách khu vực', value: regionLines || '—', inline: false }, { name: 'LN theo đơn A', value: orderLines || '—', inline: false } ] });
return [{ json: { docs_body, notify_body } }];
